const styles=new CSSStyleSheet;styles.replaceSync("/*\n * Copyright 2018 The Chromium Authors. All rights reserved.\n * Use of this source code is governed by a BSD-style license that can be\n * found in the LICENSE file.\n */\n\n.tree-outline {\n  padding-left: 0;\n}\n\n.tree-outline > ol {\n  padding-bottom: 5px;\n  border-bottom: solid 1px var(--sys-color-divider);\n}\n\n.tree-outline > .parent {\n  user-select: none;\n  font-weight: bold;\n  color: var(--color-text-primary);\n  margin-top: -1px;\n  display: flex;\n  align-items: center;\n  height: 26px;\n}\n\n.tree-outline li {\n  padding-left: 5px;\n  line-height: 20px;\n}\n\n.tree-outline li:not(.parent) {\n  display: block;\n  margin-left: 10px;\n}\n\n.tree-outline li:not(.parent)::before {\n  display: none;\n}\n\n.tree-outline .header-name {\n  color: var(--color-text-secondary);\n  display: inline-block;\n  margin-right: 0.25em;\n  font-weight: bold;\n  vertical-align: top;\n  white-space: pre-wrap;\n}\n\n.tree-outline .header-separator {\n  user-select: none;\n}\n\n.tree-outline .header-value {\n  display: inline;\n  margin-right: 1em;\n  white-space: pre-wrap;\n  word-break: break-all;\n  margin-top: 1px;\n}\n\n.tree-outline .header-toggle {\n  display: inline;\n  margin-left: 30px;\n  font-weight: normal;\n  color: var(--color-text-disabled);\n}\n\n.tree-outline .header-toggle:hover {\n  --override-header-hover-color: rgb(20% 20% 45%);\n\n  color: var(--override-header-hover-color);\n}\n\n.-theme-with-dark-background .tree-outline .header-toggle:hover,\n:host-context(.-theme-with-dark-background) .tree-outline .header-toggle:hover {\n  --override-header-hover-color: rgb(140 140 204);\n}\n\n.tree-outline .error-log {\n  color: var(--color-red);\n  display: inline-block;\n  margin-right: 0.25em;\n  margin-left: 0.25em;\n  font-weight: bold;\n  vertical-align: top;\n  white-space: pre-wrap;\n}\n\n.tree-outline .hex-data {\n  display: block;\n  word-break: break-word;\n  margin-left: 20px;\n}\n\n.tree-outline .error-field {\n  color: var(--color-red);\n}\n\n.prompt-icon {\n  margin-top: 2px;\n}\n\n/*# sourceURL=signedExchangeInfoTree.css */\n");export default styles;